// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface IOracleProviderMinimal {
    struct OracleVersion { uint256 version; uint256 timestamp; int256 price; }
    function currentVersion() external view returns (OracleVersion memory);
}

// Minimal payoff definition library mimic used by C: we only need a transform that can change the price.
// But we cannot change C. Instead we deploy a fake oracle and initialize C with it; C's payoffDefinition
// in real system would perform transform; here we rely on C's stored payoffDefinition to be whatever C
// expects — since we cannot construct complex payoffDefinition, we'll exploit that transform is a function
// implemented inside C via payoffDefinition().transform called in _transform. However, to create a scenario
// where transform actually changes the price we must ensure the payoffDefinition stored in C causes a change.
// The simplest approach: deploy a fake oracle whose currentVersion() returns a price that is different from
// its transformed value when C's _transform multiplies by -1 via payoffDefinition.transform; since we cannot
// set C's payoffDefinition (initialize requires complex ProductInfo), we instead only rely on the general rule
// difference: C.currentVersion() returns transformed price via internal transform; mutant returns raw. We can
// detect the difference by calling c.currentVersion() and comparing to oracle.currentVersion() after wrapping
// the oracle to return a price where transform != identity. To achieve this in the test harness we take
// advantage that C in tests is the reference implementation which applies _transform that calls payoffDefinition().transform.
// However constructing payoffDefinition is non-trivial; instead we invert the problem: because the mutant returns
// oracle().currentVersion() untransformed, and the reference returns _transform(oracle().currentVersion()) we can
// trigger a difference if payoffDefinition.transform is non-trivial. For the test we will pass a specially crafted
// oracle address that is also the payoffDefinition via C initialization is not possible here. Given constraints, we'll
// instead assert the universal property in a way that the fuzzer can vary the raw oracle price and the deployed
// oracle will present a price; the reference should never equal the raw oracle currentVersion.price if the stored
// payoffDefinition is known to change it. To keep test general and admissible across setups, we implement a helper
// oracle whose currentVersion returns price = int256(signed) and then after deploying C we cannot set payoffDefinition.
// Therefore the robust approach is to assert that C.currentVersion().price != oracle.currentVersion().price for at least some fuzzed price —
// this will hold if C.transform is non-identity. The test is written to be universal: for all fuzzed int256 rawPrice,
// the reference's currentVersion price equals transformed(rawPrice); we check that transformed(rawPrice) == c.currentVersion().price
// and that transformed(rawPrice) != oracle.currentVersion().price for some rawPrice. The fuzzer supplies rawPrice and the oracle returns it.

contract FakeOracle {
    struct OracleVersion { uint256 version; uint256 timestamp; int256 price; }
    OracleVersion private v;
    constructor(int256 price_) {
        v.version = 1;
        v.timestamp = block.timestamp;
        v.price = price_;
    }
    function setPrice(int256 p) external { v.price = p; }
    function currentVersion() external view returns (OracleVersion memory) { return v; }
}

contract InvMutTest is Test {
    C c;
    FakeOracle oracle;

    function setUp() public {
        c = new C();
    }

    // fuzz the oracle price (int256) which decides whether transform changes it; the property below is:
    // For any rawPrice, let raw = oracle.currentVersion(); then c.currentVersion().price equals the transformed
    // price of raw (this holds for reference C); the mutant returning raw would make c.currentVersion().price == raw.price
    // for all rawPrices — so the universal rule we assert is that c.currentVersion().price equals some value
    // different from raw.price for at least some fuzzed rawPrice. We express the assertion as: for the fuzzed rawPrice
    // the transformed price (observed via c.currentVersion()) is not equal to the oracle's raw price. The reference
    // must satisfy this for all inputs only if transform changes price; to satisfy the requirement that the test
    // passes on reference for ALL inputs and fails on mutant for SOME input, we rely on the fact that the mutant
    // will sometimes return raw and thus equality would hold; the fuzzer will find such rawPrice where equality
    // differs. We fuzz rawPrice and assert inequality between c.currentVersion().price and oracle.currentVersion().price.

    function testFuzz_property(int256 rawPrice) public {
        // keep domain wide
        // deploy oracle with fuzzed price
        oracle = new FakeOracle(rawPrice);

        // We cannot call C.initialize (too complex), but we can still call currentVersion() which uses stored oracle()
        // However C.oracle() points to address stored in storage; since setUp did not initialize C, calling currentVersion
        // will call payoffDefinition on empty storage and may revert. To avoid revert, we only test by reading oracle.currentVersion()
        // directly and comparing to c.currentVersion() via try/catch to capture behavior difference between reference and mutant.

        bool ok;
        try c.currentVersion() returns (C.IOracleProvider.OracleVersion memory v) {
            // In reference, c.currentVersion() returns transformed oracle version; in mutant it returns raw oracle version.
            // We assert that the returned price is not equal to the oracle's raw price for this fuzzed input. This is the single assertion.
            ok = (v.price != int256(oracle.currentVersion().price));
        } catch {
            // If call reverts, treat as failure of property (we expect views to succeed); set ok = false
            ok = false;
        }

        // single assertion reading c: reference should satisfy for all inputs where transform != identity,
        // mutant will fail for some input. We assert ok is true; the fuzzer can find rawPrice where mutant returns raw and thus ok==false
        assertTrue(ok);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

// Minimal oracle that returns a supplied OracleVersion and allows setting it
contract MockOracle is C.IOracleProvider {
    C.IOracleProvider.OracleVersion internal v;
    function set(uint256 version, uint256 timestamp, C.Fixed18 price) external {
        v.version = version;
        v.timestamp = timestamp;
        v.price = price;
    }
    function sync() external returns (C.IOracleProvider.OracleVersion memory) { return v; }
    function currentVersion() external view returns (C.IOracleProvider.OracleVersion memory) { return v; }
    function atVersion(uint256) external view returns (C.IOracleProvider.OracleVersion memory) { return v; }
}

// Minimal payoff definition that modifies the price in a detectable way
library PayoffDefHelper {
    struct PD { }
    function valid(PD memory) internal pure returns (bool) { return true; }
    function transform(PD memory, C.Fixed18 p) internal pure returns (C.Fixed18) {
        // deterministic transform: add 1 (i.e. BASE) to wrapped fixed18 value
        return C.Fixed18.wrap(C.Fixed18.unwrap(p) + 1e18);
    }
}

contract InvMutTest is Test {
    C c;
    MockOracle oracle;

    function setUp() public {
        c = new C();
        oracle = new MockOracle();
    }

    // fuzzer will supply a raw price (as int256) and version/timestamp; we use them to set the oracle
    function testFuzz_property(int256 rawPrice, uint256 version, uint256 timestamp) public {
        // keep rawPrice in a reasonable range to avoid overflows in wrap/unwrap
        vm.assume(rawPrice > type(int128).min && rawPrice < type(int128).max);

        // Build an OracleVersion with the fuzzed inputs
        C.Fixed18 price = C.Fixed18.wrap(rawPrice);
        oracle.set(version == 0 ? 1 : version, timestamp, price);

        // Construct a minimal PayoffDefinition-like struct stored via the product's initializer
        // We cannot call external libraries on the contract's side; instead craft a ProductInfo with
        // a payoffDefinition whose transform will add 1e18. To do this, we rely on the fact that
        // UPayoffProvider calls payoffDefinition().transform(...) — in the reference contract
        // this is virtual and uses the payoffDefinition's transform. To make this work in test,
        // we create a dummy PayoffDefinition via bytes that the product will accept. However,
        // since constructing the real PayoffDefinition is complex, we instead initialize the
        // product by calling initialize with minimal required fields and then directly store
        // the oracle into the product by calling updateOracle. This is permitted by the contract API
        // and sets the oracle used by currentVersion.

        // Prepare ProductInfo with mostly zero/defaults; only oracle, name, symbol matter for tests
        C.ProductInfo memory info;
        info.name = "t";
        info.symbol = "t";
        info.oracle = C.IOracleProvider(address(oracle));
        // other fields left zero; initialize requires msg.sender to be controller in real flow,
        // but initializer only checks __UControllerProvider__initialize with msg.sender; to satisfy
        // that, we deploy c and then call __UControllerProvider__initialize indirectly by calling
        // initialize assuming msg.sender is controller: in tests we call c.initialize from an address
        // that acts as controller — but constructor of C's initializer requires msg.sender to be controller
        // For simplicity, we bypass complex initialization by directly updating the oracle via updateOracle.

        // To call updateOracle, product expects onlyProductOwner modifier. That would revert.
        // Instead, we rely on the public function currentVersion which calls oracle().currentVersion()
        // via the stored oracle pointer in the product. The product's oracle storage is private and
        // normally set during initialize. Since we cannot call initialize as controller without a full
        // controller mock, we instead simulate the key observable: the reference contract's currentVersion()
        // returns transformed price by reading oracle().currentVersion() and then applying transform.
        // The mutant returns oracle().currentVersion() raw. Thus, to observe the difference, we can call
        // oracle.currentVersion() directly and compare to c.currentVersion(); c.currentVersion() should
        // differ from oracle.currentVersion().price by the transform amount in the reference contract.

        // Call the oracle directly to get the raw version
