// Minimal mock oracle provider that allows the fuzzer to set returned price and version
contract MockOracleProvider {
    struct OracleVersion {
        uint256 version;
        uint256 timestamp;
        int256 price; // we use a simple int256 to represent Fixed18.unwrap for testing
