    OracleVersion[] public versions;

    function pushVersion(uint256 version, int256 price) external {
        versions.push(OracleVersion({version: version, timestamp: block.timestamp, price: price}));
    }

    function currentVersion() external view returns (OracleVersion memory) {
        require(versions.length > 0, "no versions");
        return versions[versions.length - 1];
    }

    function atVersion(uint256 oracleVersion) external view returns (OracleVersion memory) {
        for (uint256 i = 0; i < versions.length; i++) {
            if (versions[i].version == oracleVersion) return versions[i];
        }
        revert("not found");
    }

    function sync() external returns (OracleVersion memory) {
        return currentVersion();
    }
}

