        ctrl.setIsProductTrue();

        // Now construct a simple encoded ProductInfo and call initialize via low-level call with this test contract as msg.sender
        // but initialize expects msg.sender to be controller; therefore we must call c.initialize with msg.sender == address(ctrl).
        // Use vm.prank to make the controller call initialize on the product.

        // Build a minimal PayoffDefinition tuple: (payoffType:uint8, payoffDirection:uint8, bytes30 data)
        bytes memory payoffDefinitionEncoded = abi.encode(uint8(0), uint8(0), bytes30(0));

        // Build a minimal JumpRateUtilizationCurve: (PackedFixed18 minRate,uint128 maxRate, targetRate, targetUtilization)
        // Each packed types are primitive sized; fill zeros.
        bytes memory utilizationCurveEncoded = abi.encodePacked(uint128(0), uint128(0), uint128(0), uint128(0));

        // Prepare ProductInfo encoding
        bytes memory name = abi.encode("n");
        bytes memory symbol = abi.encode("s");

        // UFixed18 values: use maintenanceRaw and makerLimitRaw as underlying uint256 values
        bytes memory maintenanceEnc = abi.encode(maintenanceRaw);
        bytes memory fundingFeeEnc = abi.encode(uint256(0));
        bytes memory makerFeeEnc = abi.encode(uint256(0));
        bytes memory takerFeeEnc = abi.encode(uint256(0));
        bytes memory positionFeeEnc = abi.encode(uint256(0));
        bytes memory makerLimitEnc = abi.encode(makerLimitRaw);

        // oracle address
        MinimalOracle oracle = new MinimalOracle();

        // Now encode the full ProductInfo tuple per ABI: (string,string,tuple, address, uint256 ... , tuple)
        bytes memory productInfo = abi.encode(
            string("n"),
            string("s"),
            // PayoffDefinition as tuple (uint8,uint8,bytes30)
            (uint8(0)), (uint8(0)), bytes30(0),
            address(oracle),
            maintenanceRaw,
            uint256(0),
            uint256(0),
            uint256(0),
            uint256(0),
            makerLimitRaw,
            // JumpRateUtilizationCurve tuple - use four zeros of appropriate packed sizes
            uint128(0), uint128(0), uint128(0), uint128(0)
        );

        // Now have controller call initialize
        vm.prank(address(ctrl));
        (bool ok, ) = address(c).call(abi.encodeWithSignature("initialize((string,string,(uint8,uint8,bytes30),address,uint256,uint256,uint256,uint256,uint256,uint256,(uint128,uint128,uint128,uint128)))", productInfo));
