        // Attempt a direct call via try with constructed typed call may fail compile-time; so we don't keep further attempts.

        // After initialization attempt (if succeeded), call maintenance() and makerLimit() and assert they are equal to the stored maintenance
        // The general rule: maintenance() returns the stored maintenance value. We check that by calling c.maintenance(address(this)) and
        // comparing to c.makerLimit() only when they differ the mutant will be caught. Since this test must pass on reference for all inputs
        // and fail on mutant for some, we assert that c.maintenance() equals the maintenanceRaw value we attempted to set.

        // Read maintenance via try/catch to avoid revert
        bool okMaint;
        try c.maintenance(address(this)) returns (bytes memory) {
            okMaint = true;
        } catch {
            okMaint = false;
        }

        // We assert that the call does not revert and returns the maintenanceRaw value encoded as UFixed18 underlying uint256.
        // Read the returned UFixed18 by calling the function and capturing value
        // To obey the single-assert rule and to use a public getter, call maintenance and makerLimit and compare equality to maintenanceRaw
        UFixed18Wrapper retMaint;
        UFixed18Wrapper retMaker;
        // We cannot type UFixed18 here; instead read using low-level staticcall and decode as uint256
        (bool succ1, bytes memory data1) = address(c).staticcall(abi.encodeWithSignature("maintenance(address)", address(this)));
        (bool succ2, bytes memory data2) = address(c).staticcall(abi.encodeWithSignature("makerLimit()"));

        // If either staticcall failed, make the assert false (the correct contract should not revert for maintenance getter)
        if (!succ1 || !succ2) {
            assertTrue(false);
        }

        uint256 gotMaintenance = abi.decode(data1, (uint256));
        uint256 gotMakerLimit = abi.decode(data2, (uint256));

        // SINGLE assertion: on the correct contract, maintenance() must equal the stored maintenance value we provided (maintenanceRaw)
        // We check that by asserting gotMaintenance == maintenanceRaw. The mutant that returns makerLimit() will only match when maintenanceRaw == makerLimitRaw;
        // the fuzzer can find makerLimitRaw differing to expose the mutant.
        assertTrue(gotMaintenance == maintenanceRaw);
    }
}

