        // Create the tuple matching ProductInfo in order. For the nested structs, we must match their ABI encoding.
        // Define the ProductInfo tuple types explicitly in abi.encode to match the calldata layout.

        // PayoffDefinition in source is (PayoffType, PayoffDirection, bytes30 data) where enums are uint8
        // JumpRateUtilizationCurve is (PackedFixed18 minRate, PackedFixed18 maxRate, PackedFixed18 targetRate, PackedUFixed18 targetUtilization)

        // Build ProductInfo tuple
        bytes memory productInfoCalldata = abi.encode(
            name,
            symbol,
            // PayoffDefinition tuple
            uint8(0), // payoffType
            uint8(0), // payoffDirection
            bytes30(0),
            address(oracle),
            maintenanceRaw,
            uint256(0), // fundingFee
            uint256(0), // makerFee
            uint256(0), // takerFee
            uint256(0), // positionFee
            uint256(0), // makerLimit
            // JumpRateUtilizationCurve tuple
            int128(0), // minRate
            int128(0), // maxRate
            int128(0), // targetRate
            uint128(0) // targetUtilization
        );

        // Call initialize using low-level call with the encoded ProductInfo as the single argument.
        // The selector for initialize(ProductInfo) can be obtained via abi.encodeWithSelector
        bytes4 sel = bytes4(keccak256("initialize((string,string,(uint8,uint8,bytes30),address,uint256,uint256,uint256,uint256,uint256,uint256,(int128,int128,int128,uint128)))"));
        // But solidity may mangle tuple types; instead use C.initialize selector by reading from interface is complex.
        // Simpler: call initialize by constructing the ProductInfo in memory via an inline call

        // To avoid the ABI-selector complexity, we can call initialize through a wrapper contract that has the correct typed ProductInfo.
        // Deploy an initializer helper that calls c.initialize with a strongly-typed ProductInfo.

        InitializerHelper helper = new InitializerHelper(c);

        // Now call helper.initializeWithMaintenance with the fuzzed maintenanceRaw
        helper.initializeWithMaintenance(name, symbol, DummyPayoffDefinition({payoffType:0, payoffDirection:0, data:bytes30(0)}), oracle, maintenanceRaw);

        // After initialization, read maintenance via the getter
        // The correct contract returns exactly the stored maintenance; the mutant returns double.
        UFixed18 readMaintenance = c.maintenance();

        // The property: readMaintenance equals the stored maintenance value.
        // We cannot directly read the private storage _maintenance, but we initialized with maintenanceRaw, so expect readMaintenance == UFixed18.wrap(maintenanceRaw)
        // To check that, we assert that if maintenanceRaw is zero, both agree trivially; if non-zero, reference returns maintenanceRaw, mutant returns 2*maintenanceRaw causing assertion failure for some inputs.

        // Build expected UFixed18 by calling through helper getter that returns what we set (the canonical stored value via a public view on helper reading c.maintenance())
        // Actually c.maintenance() is the getter we already called. We need expected value equal to the value we initialized with.

        // Compute expected as maintenanceRaw (wrapped). Since UFixed18 has no accessible type here, compare via uint256 by encoding the UFixed18 returned value using abi.decode from the return.
        // But c.maintenance() returns UFixed18 which in ABI is uint256; solidity will let us compare by decoding back to uint256 using abi.encodePacked.

        uint256 returnedRaw = abi.decode(abi.encode(readMaintenance), (uint256));

        // Now assert that returnedRaw equals maintenanceRaw. This holds for the reference but fails for mutant when maintenanceRaw != 0.
        assertTrue(returnedRaw == maintenanceRaw);
    }
}

// Minimal helper contracts and types
struct DummyPayoffDefinition { uint8 payoffType; uint8 payoffDirection; bytes30 data; }

contract DummyOracle {
    struct OracleVersion { uint256 version; uint256 timestamp; int256 price; }
    function sync() external returns (OracleVersion memory) {
        return OracleVersion({version:1, timestamp:block.timestamp, price: int256(0)});
    }
    function currentVersion() external view returns (OracleVersion memory) {
        return OracleVersion({version:1, timestamp:block.timestamp, price: int256(0)});
    }
    function atVersion(uint256) external view returns (OracleVersion memory) {
        return OracleVersion({version:1, timestamp:block.timestamp, price: int256(0)});
    }
}

contract InitializerHelper {
    C c;
    constructor(C _c) { c = _c; }

    // We reuse the actual ProductInfo type by matching parameters sufficiently to call C.initialize
    function initializeWithMaintenance(
        string memory name,
        string memory symbol,
        DummyPayoffDefinition memory payoffDef,
        DummyOracle oracle,
        uint256 maintenanceRaw
    ) public {
        // Build the ProductInfo struct in-place by calling C.initialize with typed tuple matching the contract's struct
        // Define local struct types matching C.ProductInfo layout
        // We can't directly construct ProductInfo type here because it's defined in imported C; however solidity allows passing a tuple that matches the ABI.
        // The initialize function expects (string,string,(uint8,uint8,bytes30),address,uint256,uint256,uint256,uint256,uint256,uint256,(int128,int128,int128,uint128))

        // Call via low-level call using selector of initialize and abi.encode with the matching tuple layout
        bytes memory payload = abi.encodeWithSelector(
            bytes4(keccak256("initialize((string,string,(uint8,uint8,bytes30),address,uint256,uint256,uint256,uint256,uint256,uint256,(int128,int128,int128,uint128)))")),
            // The tuple as per ABI
            name,
            symbol,
            // payoffDefinition tuple
            payoffDef.payoffType,
            payoffDef.payoffDirection,
            payoffDef.data,
            address(oracle),
            maintenanceRaw,
            uint256(0),
            uint256(0),
            uint256(0),
            uint256(0),
            uint256(0),
            // utilization curve tuple
            int128(0),
            int128(0),
            int128(0),
            uint128(0)
        );

        (bool ok, bytes memory) = address(c).call(payload);
        require(ok, string(abi.encodePacked("initialize failed: ", abi.encodePacked(bytes4(keccak256("initialize(...)"))))));
    }
}

