pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the stored maintenance value by passing it through the initializer's ProductInfo
    // we build a minimal ProductInfo with maintenance = fuzzedMaintenance and initialize c
    function testFuzz_property(uint256 fuzzedMaintenance) public {
        // keep the fuzzed maintenance in a wide admissible range
        uint256 m = bound(fuzzedMaintenance, 0, type(uint128).max);

        // construct a minimal ProductInfo on the stack by encoding and calling initialize via low-level call
        // We cannot construct the full ProductInfo type here without importing many types; instead reuse the fact
        // that initialize is external and expects a ProductInfo calldata struct — we craft calldata manually.
        // ProductInfo layout (in order): string name, string symbol, PayoffDefinition payoffDefinition, address oracle,
        // UFixed18 maintenance, UFixed18 fundingFee, UFixed18 makerFee, UFixed18 takerFee, UFixed18 positionFee,
        // UFixed18 makerLimit, JumpRateUtilizationCurve utilizationCurve
        // To avoid complexity, we call initialize with mostly zero/empty fields but set maintenance to m by
        // using abi.encode with placeholder bytes for types; this is sufficient because the contract reads storage
        // through _update... which accepts UFixed18 values represented as uint256 in calldata.

        // Build a simple ProductInfo with two dynamic strings and then many fixed-size values. We'll craft
        // a simple ABI-encoded calldata matching: initialize(ProductInfo)
        string memory name = "n";
        string memory symbol = "s";

        // For the oracle and payoffDefinition we use zero values (address(0), zeros) — initializer will call
        // __UControllerProvider__initialize expecting msg.sender to be controller; however the C.initialize expects
        // msg.sender to be IController and uses it as controller in __UControllerProvider__initialize.
        // To satisfy that, we must call initialize from an address that behaves as a controller with minimal interface.
        // We'll deploy a tiny helper ControllerStub that implements the functions used during initialize.

        ControllerStub controller = new ControllerStub();
        // craft ProductInfo with maintenance = UFixed18.wrap(m * 1e18) but in our simplified setting UFixed18 is uint256
        // The contract's initialize expects productInfo_.maintenance as UFixed18 — represented as uint256 in ABI.

        // Build calldata using abi.encodeWithSignature
        // We must provide many parameters; to keep it simple, set most numeric values to zero and oracle to address(0).
        // The exact layout of nested structs is complex, but solidity can ABI-encode the ProductInfo struct if we declare
        // a matching struct in this file. To avoid that, instead we perform a low-level call to the contract's
        // initialize by encoding the expected struct via a helper that has the same ProductInfo type.

        // Deploy an InitializerHelper that has the same ProductInfo type and calls c.initialize with a proper struct.
        InitializerHelper helper = new InitializerHelper(c);

        // call helper to initialize c with maintenance = m (as raw UFixed18 uint256 units)
        helper.initializeOnBehalf(address(controller), m);

        // Now call maintenance() and assert it equals the stored maintenance (m) for the reference contract.
        // The mutant doubles the returned maintenance for any non-zero m, so the assertion will fail for some fuzz inputs.
        UFixed18Wrapper.UFixed18 memory returned = UFixed18Wrapper.wrapUFixed18(c.maintenance(address(0)));
        uint256 returnedValue = returned.unwrap();

        // The stored maintenance was set by helper.initializeOnBehalf to m (as raw units), so returnedValue must equal m.
        assertTrue(returnedValue == m, "maintenance() must return stored maintenance value exactly");
    }
}

// Minimal controller stub with functions referenced by initialize; returns default values
contract ControllerStub {
    function owner() external view returns (address) { return address(this); }
}

// Helper to match ProductInfo struct and call c.initialize correctly
contract InitializerHelper {
    C public c;
    constructor(C _c) { c = _c; }

    struct PayoffDefinition { uint8 payoffType; uint8 payoffDirection; bytes30 data; }
    struct JumpRateUtilizationCurve { int128 minRate; int128 maxRate; int128 targetRate; uint128 targetUtilization; }
    struct ProductInfo {
        string name;
        string symbol;
        PayoffDefinition payoffDefinition;
        address oracle;
        uint256 maintenance; // UFixed18
        uint256 fundingFee;
        uint256 makerFee;
        uint256 takerFee;
        uint256 positionFee;
        uint256 makerLimit;
        JumpRateUtilizationCurve utilizationCurve;
    }

    function initializeOnBehalf(address controller, uint256 maintenanceRaw) external {
        ProductInfo memory info;
        info.name = "n";
        info.symbol = "s";
        info.payoffDefinition = PayoffDefinition({payoffType: 0, payoffDirection: 0, data: bytes30(0)});
        info.oracle = address(0);
        info.maintenance = maintenanceRaw;
        info.fundingFee = 0;
        info.makerFee = 0;
        info.takerFee = 0;
        info.positionFee = 0;
        info.makerLimit = 0;
        info.utilizationCurve = JumpRateUtilizationCurve({minRate: 0, maxRate: 0, targetRate: 0, targetUtilization: 0});

        // call initialize with msg.sender being the controller: use a low-level call via delegatecall is not possible,
        // so we simply call c.initialize from this contract and rely on __UControllerProvider__initialize expecting
        // msg.sender to be controller — but since that function checks Address.isContract(address(controller_)) and then
        // stores controller_, we pass controller as msg.sender by making controller call this helper, which then calls c.
        // To simplify, we bypass that by having controller be EOA in tests; however setUp uses new C(), so controller checks
        // only that address is a contract in __UControllerProvider__initialize; to avoid revert we pass a contract address.

        // Instead we perform a two-step: first have the controller (the caller of this function) call this helper which then
        // calls c.initialize. In our test we passed controller as a ControllerStub contract instance address, but we cannot
        // force its msg.sender here. To ensure c.initialize accepts the controller, we call c.initialize directly from this helper
        // and hope the minimal checks inside initialize accept it. If the reference contract requires specific controller behavior,
        // this helper mimics expected calls sufficiently for the purpose of setting maintenance.

        c.initialize(info);
    }
}

// Small wrapper to treat UFixed18 as uint256 for extracting stored value via the public maintenance getter
library UFixed18Wrapper {
    struct UFixed18 { uint256 v; }
    function wrapUFixed18(uint256 x) internal pure returns (UFixed18 memory) { return UFixed18({v: x}); }
    function unwrap(UFixed18 memory u) internal pure returns (uint256) { return u.v; }
}
